    for (; ; ) {
        c = (unsigned char)(src[i]);
        if (c == 0) {
            return (char *)(0);
        }
        if ((((q == 0) && (depth == 0)) && (c == ';'))) {
            break;
        }
        if (((q == 0) && ((c == '"') || (c == '\'')))) {
            q = c;
        }
        else {
            if (((q != 0) && (c == q))) {
                q = 0;
            }
            else {
                if ((((q != 0) && (c == '\\')) && src[(i + 1)])) {
                    i++;
                }
                else {
                    if (((q == 0) && (c == '('))) {
                        depth++;
                    }
                    else {
                        if (((q == 0) && (c == ')'))) {
                            depth--;
                        }
                    }
                }
            }
        }
        i++;
    }
    end = i;
